UPDATE public."noticeTemplateV2" SET remarks = '客户3天内未重新提交年审信息', "createTime" = '2023-07-11 04:15:21.570830 +00:00', "updateTime" = '2025-07-10 11:33:47.475706 +00:00', "deleteTime" = null, version = 13, templates = '{"emails": [{"email": {"text": "尊敬的客户 <%verifiedName%>：\n您的实名认证信息还未完成更新确认。\n请您务必在<%time%>完成实名认证信息的检查和更新，以确保您的账户正常使用。如果未能及时更新，可能会影响您的账户功能和服务。\n<a href=\"<%webUrl%>/#/app/dashboard?eventName=to-odd-account-review&eventData=<%eventData%>\">去办理</a>", "allow": true, "tenant": true, "template": "customUniteNotice", "topicName": "[<%emailPrefix%>]请尽快完成您的名认证信息更新"}, "language": "zh"}, {"email": {"text": "Dear <%verifiedName%>,\nOur records indicate that your Know Your Customer (KYC) information update remains incomplete. This update is essential to maintain compliance with regulatory requirements and ensure continued access to all account services.\nPlease complete this important update by <%time%> to prevent any interruption to your account functionality. The update process requires your attention to verify and confirm your information in accordance with our compliance standards.\nTo complete your KYC information update:\n1. Access your secure account portal using your credentials\n2. Navigate to the \"\"To do\"\" section\n3. Select the pending KYC update notice\n4. Review and complete all required fields\nFailure to complete this update by the specified deadline may result in limitations to your account services and functionality as required by our regulatory obligations.", "allow": true, "tenant": true, "template": "customUniteNotice", "topicName": "[<%emailPrefix%>]REMINDER: KYC Information Update Required by <%time%> - <%displayId%>"}, "language": "en"}], "sockets": [{"socket": {"text": "尊敬的客户 <%verifiedName%>：\n您的实名认证信息还未完成更新确认。\n请您务必在<%time%>完成实名认证信息的检查和更新，以确保您的账户正常使用。如果未能及时更新，可能会影响您的账户功能和服务。\n<a href=\"<%webUrl%>/#/app/dashboard?eventName=to-odd-account-review&eventData=<%eventData%>\">去办理</a>", "type": "Other", "allow": true, "title": "通知-请尽快完成您的名认证信息更新", "tenant": true, "subType": "notice", "notificationToAccountType": "User"}, "language": "zh"}, {"socket": {"text": "Hi <%verifiedName%>：\nYour identity verification information is still pending confirmation for updates.\nPlease make sure to complete the inspection and update of identity verification information by <%time%> to ensure the normal usage of your account. Failure to update in a timely manner may impact the functionality and services of your account.\n<a href=\"<%webUrl%>/#/app/dashboard?eventName=to-odd-account-review&eventData=<%eventData%>\">to go and process</a>", "type": "Other", "allow": true, "title": "Notice-Please update your identity verification information promptly", "tenant": true, "subType": "notice", "notificationToAccountType": "User"}, "language": "en"}], "qbitNotices": [{"language": "zh", "qbitNotice": {"allow": true, "content": {"level": "blue", "content": "<%at%>, <%verifiedName%>(<%displayId%>)需在 <%time%>前更新KYC信息，否则将影响账户的正常使用", "contentEn": "<%at%>, <%verifiedName%>(<%displayId%>)''s  needs to update KYC info by <%time%>"}, "receiveId": "", "templateType": "Notice", "allowInterlaceRobot": true}}], "adminSockets": [], "feiShuRobots": [], "earmarkEmails": []}', label = '账户审查', "templateParams" = '[{"name": "verifiedName", "type": "string", "remarks": "账户名称", "require": false}, {"name": "webUrl", "type": "string", "remarks": "商户端链接", "require": false}, {"name": "emailPrefix", "type": "string", "remarks": "邮件标题前缀", "require": false}, {"name": "serviceApiUrl", "type": "string", "remarks": "服务器域名", "require": false}, {"name": "mobileUrl", "type": "string", "remarks": "移动端链接", "require": false}, {"name": "time", "type": "string", "remarks": "时间", "require": true}, {"name": "eventData", "type": "string", "remarks": "事件参数", "require": true}, {"name": "displayId", "type": "string", "remarks": "", "require": true}, {"name": "at", "type": "string", "remarks": "", "require": true}]', "templateName" = 'Odd_Account_Review_Notice', node = 'node' WHERE id = '4ccba567-a2af-4181-82e0-dedf28b94846';
UPDATE public."noticeTemplateV2" SET remarks = '合规审核-需要客户更新ODD信息', "createTime" = '2023-07-11 04:07:09.140443 +00:00', "updateTime" = '2025-07-10 11:33:26.938401 +00:00', "deleteTime" = null, version = 15, templates = '{"emails": [{"email": {"text": "尊敬的客户 <%verifiedName%>：\n因合规政策原因，您的实名认证信息需更新确认。\n请您务必在7天内完成信息的检查和更新，以确保您的账户正常运营，如未及时更新可能会影响您的正常使用。\n<a href=\"<%webUrl%>/#/app/dashboard?eventName=to-odd-account-review&eventData=<%eventData%>\">去办理</a>", "allow": true, "tenant": true, "template": "customUniteNotice", "topicName": "[<%emailPrefix%>]您的实名认证信息需更新确认"}, "language": "zh"}, {"email": {"text": "Dear <%verifiedName%>,\nOur Compliance team has identified that your Know Your Customer (KYC) information requires review and updating to maintain regulatory compliance and ensure the security of your account.\nTo update your KYC information and maintain uninterrupted account access, please:\n1. Access your secure account portal using your credentials\n2. Navigate to the \"\"To do\"\" section\n3. Locate the KYC update notification\n4. Review and update your information according to the specified requirements\nThis update must be completed within 7 days from the date of this notification. Failure to update your KYC information within this timeframe may result in temporary restrictions to certain account features or services in accordance with our regulatory obligations.\n\n", "allow": true, "tenant": true, "template": "customUniteNotice", "topicName": "[<%emailPrefix%>]Important: KYC Information Update Required Within 7 Days - <%displayId%>"}, "language": "en"}], "sockets": [{"socket": {"text": "尊敬的客户 <%verifiedName%>：\n因合规政策原因，您的实名认证信息需更新确认。\n请您务必在7天内完成信息的检查和更新，以确保您的账户正常运营，如未及时更新可能会影响您的正常使用。\n<a href=\"<%webUrl%>/#/app/dashboard?eventName=to-odd-account-review&eventData=<%eventData%>\">去办理</a>", "type": "Other", "allow": true, "title": "通知-您的实名认证信息需更新确认", "tenant": true, "subType": "notice", "notificationToAccountType": "User"}, "language": "zh"}, {"socket": {"text": "Hi <%verifiedName%>：\nDue to compliance policies, we kindly request your confirmation to update your identity verification information. \nIt is essential that you complete the information check and update within 7 days to ensure the normal operation of your account. Failure to update in a timely manner may affect your regular usage.\n<a href=\"<%webUrl%>/#/app/dashboard?eventName=to-odd-account-review&eventData=<%eventData%>\">to go and process</a>", "type": "Other", "allow": true, "title": "Notice-Please confirm the update of your identity verification information", "tenant": true, "subType": "notice", "notificationToAccountType": "User"}, "language": "en"}], "qbitNotices": [{"language": "zh", "qbitNotice": {"allow": true, "content": {"level": "blue", "content": "<%at%>, <%verifiedName%> (<%displayId%>)''需更新KYC信息", "contentEn": "<%at%>, <%verifiedName%> (<%displayId%>)''s needs to update KYC info"}, "receiveId": "", "templateType": "Notice", "allowInterlaceRobot": true}}], "adminSockets": [], "feiShuRobots": [], "earmarkEmails": []}', label = '账户审查', "templateParams" = '[{"name": "verifiedName", "type": "string", "remarks": "账户名称", "require": false}, {"name": "webUrl", "type": "string", "remarks": "商户端链接", "require": false}, {"name": "emailPrefix", "type": "string", "remarks": "邮件标题前缀", "require": false}, {"name": "serviceApiUrl", "type": "string", "remarks": "服务器域名", "require": false}, {"name": "mobileUrl", "type": "string", "remarks": "移动端链接", "require": false}, {"name": "eventData", "type": "string", "remarks": "事件参数", "require": true}, {"name": "displayId", "type": "string", "remarks": "", "require": true}, {"name": "at", "type": "string", "remarks": "", "require": true}]', "templateName" = 'Odd_Account_Review_Request', node = 'node' WHERE id = 'dd5a44d4-cd82-430f-84c3-6dda90c0df94';


